window.RP_SESSION={"id":"S-e6062bb55b1c","messages":[{"id":"RP-0133381","time":"2026-04-27T19:28:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 펜 촉을 꺼내들고, 무언가를 정리해냅니다. 뒷정리, 안했고. 테론 입단속···. 시켜야지.","characters":["P-b6d81d634c6e"]},{"id":"RP-0133382","time":"2026-04-27T19:29:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"@테론 이스트가드 , 당신의 앞에 익숙한 얼굴이 나타났습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0133383","time":"2026-04-27T19:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"편지가 테론에게 전달됩니다.\n\n불 태우세요. 확인 후 곧바로 태우는 게 좋을거에요. 장담하건데, 테론, 당신도 함께 끌려갈지도 몰라요.\n아무도 들키지 않는 곳에서 확인해요.\n\n테론을 살려온 건 제 생각에는 해야만 했던 일에 가깝다고 생각해요, 그치만, 모두가 같은 시선으로 생각하는 건 아니에요.\n\n테론은 스스로의 의지로, 여느 언데들과 같게 이 세상으로 돌아온거에요.\n\n확인했다면, 다시 강조하는데. 불태우세요. 흔적도, 재 하나도 남지 않게.\n\n마리우스는 편지를 내밀고, 사라졌습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0133384","time":"2026-04-27T19:43:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-0133385","time":"2026-04-27T19:43:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
